    pub const VT_TOKENS: ::flatbuffers::VOffsetT = 28;
    pub const VT_PAIRS: ::flatbuffers::VOffsetT = 30;
    pub const VT_COLUMN: ::flatbuffers::VOffsetT = 32;

    #[inline]
