    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args FSGArgs<'args>
    ) -> ::flatbuffers::WIPOffset<FSG<'bldr>> {
        let mut builder = FSGBuilder::new(_fbb);
        builder.add_COVERS_THROUGH(args.COVERS_THROUGH);
        builder.add_MAX_SEQ(args.MAX_SEQ);
        builder.add_MIN_SEQ(args.MIN_SEQ);
        builder.add_PREVIOUS(args.PREVIOUS);
        builder.add_SELF_OFFSET(args.SELF_OFFSET);
        if let Some(x) = args.COLUMN { builder.add_COLUMN(x); }
        if let Some(x) = args.PAIRS { builder.add_PAIRS(x); }
        if let Some(x) = args.TOKENS { builder.add_TOKENS(x); }
        if let Some(x) = args.INSTANCES { builder.add_INSTANCES(x); }
        if let Some(x) = args.LATEST { builder.add_LATEST(x); }
        if let Some(x) = args.ENTRIES { builder.add_ENTRIES(x); }
        if let Some(x) = args.REPLACES { builder.add_REPLACES(x); }
        builder.add_FEED_ID(args.FEED_ID);
        builder.add_LEVEL(args.LEVEL);
        builder.add_KIND(args.KIND);
        builder.finish()
    }

    pub fn unpack(&self) -> FSGT {
        let SELF_OFFSET = self.SELF_OFFSET();
        let PREVIOUS = self.PREVIOUS();
        let FEED_ID = self.FEED_ID();
        let KIND = self.KIND();
        let LEVEL = self.LEVEL();
        let MIN_SEQ = self.MIN_SEQ();
        let MAX_SEQ = self.MAX_SEQ();
        let COVERS_THROUGH = self.COVERS_THROUGH();
        let REPLACES = self.REPLACES().map(|x| {
            x.into_iter().collect()
        });
        let ENTRIES = self.ENTRIES().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let LATEST = self.LATEST().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let INSTANCES = self.INSTANCES().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let TOKENS = self.TOKENS().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let PAIRS = self.PAIRS().map(|x| {
            x.iter().map(|t| t.unpack()).collect()
        });
        let COLUMN = self.COLUMN().map(|x| {
            x.into_iter().collect()
        });
        FSGT {
            SELF_OFFSET,
            PREVIOUS,
            FEED_ID,
            KIND,
            LEVEL,
            MIN_SEQ,
            MAX_SEQ,
            COVERS_THROUGH,
            REPLACES,
            ENTRIES,
            LATEST,
            INSTANCES,
            TOKENS,
            PAIRS,
            COLUMN,
        }
    }

