impl ::flatbuffers::Verifiable for FSG<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<u64>("SELF_OFFSET", Self::VT_SELF_OFFSET, false)?
            .visit_field::<u64>("PREVIOUS", Self::VT_PREVIOUS, false)?
            .visit_field::<u32>("FEED_ID", Self::VT_FEED_ID, false)?
            .visit_field::<fckSegmentKind>("KIND", Self::VT_KIND, false)?
            .visit_field::<u8>("LEVEL", Self::VT_LEVEL, false)?
            .visit_field::<u64>("MIN_SEQ", Self::VT_MIN_SEQ, false)?
            .visit_field::<u64>("MAX_SEQ", Self::VT_MAX_SEQ, false)?
            .visit_field::<u64>("COVERS_THROUGH", Self::VT_COVERS_THROUGH, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, u64>>>("REPLACES", Self::VT_REPLACES, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<FMBEntry>>>>("ENTRIES", Self::VT_ENTRIES, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, FSGLatest>>>("LATEST", Self::VT_LATEST, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, FSGInstance>>>("INSTANCES", Self::VT_INSTANCES, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<FMBEntry>>>>("TOKENS", Self::VT_TOKENS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, FSGPair>>>("PAIRS", Self::VT_PAIRS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, u8>>>("COLUMN", Self::VT_COLUMN, false)?
            .finish();
        Ok(())
    }
}

