/// `size_prefixed_root_as_fsg_unchecked`.
#[inline]
pub fn size_prefixed_root_as_fsg(buf: &[u8]) -> Result<FSG<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<FSG>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `FSG` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_fsg_unchecked`.
#[inline]
pub fn root_as_fsg_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<FSG<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<FSG<'b>>(opts, buf)
}

