/// Assumes, without verification, that a buffer of bytes contains a FSG and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `FSG`.
#[inline]
pub unsafe fn root_as_fsg_unchecked(buf: &[u8]) -> FSG<'_> {
    unsafe { ::flatbuffers::root_unchecked::<FSG>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed FSG and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `FSG`.
#[inline]
pub unsafe fn size_prefixed_root_as_fsg_unchecked(buf: &[u8]) -> FSG<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<FSG>(buf) }
}

pub const FSG_IDENTIFIER: &str = "$FSG";

#[inline]
pub fn fsg_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, FSG_IDENTIFIER, false)
}

#[inline]
pub fn fsg_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, FSG_IDENTIFIER, true)
}

#[inline]
pub fn finish_fsg_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<FSG<'a>>
) {
    fbb.finish(root, Some(FSG_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_fsg_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<FSG<'a>>
) {
    fbb.finish_size_prefixed(root, Some(FSG_IDENTIFIER));
}
